from collections import Counter

def shape_cells(g):
    bg = Counter(x for row in g for x in row).most_common(1)[0][0]
    return bg, {(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x != bg and x != 1}

def transform(grid):
    g = [row[:] for row in grid]
    H, W = len(g), len(g[0])
    bg, S = shape_cells(g)
    rows = sorted({r for r,_ in S})
    cols_by_row = {r: sorted(c for rr,c in S if rr==r) for r in rows}
    fills = set()
    pair_found = False
    for r in rows:
        A = cols_by_row[r]
        if not A: continue
        for r2 in rows:
            if r2 <= r: continue
            B = set(cols_by_row[r2])
            if not B: continue
            for dc in range(-W, W+1):
                if all((c+dc) in B for c in A):
                    pair_found = True
                    for c in B:
                        cc = c - dc
                        if 0 <= cc < W and g[r][cc] == bg:
                            fills.add((r,cc))
    if pair_found:
        # solid-run propagation: longest consecutive run of shape cells in any band row
        best = None
        for r in rows:
            run = []; 
            for c in cols_by_row[r]:
                if run and c == run[-1]+1: run.append(c)
                else:
                    if best is None or len(run) > len(best): best = run[:] if len(run)>1 else best
                    run = [c]
            if best is None or len(run) > len(best): best = run[:] if len(run)>1 else best
        if best:
            for r in rows:
                for c in range(best[0], best[-1]+1):
                    if g[r][c] == bg: fills.add((r,c))
    else:
        # single copy: alternating tail extension
        for r in rows:
            if not cols_by_row[r]: continue
            b = max(cols_by_row[r])
            c = b + 2
            while c < W:
                if g[r][c] == bg: fills.add((r,c))
                c += 2
    for r,c in fills: g[r][c] = 1
    return g

